(122, 'index.php?option=com_content&view=article&id=118', 'index.php?option=com_content&view=article&id=118:panel-1&catid=9&lang=en-GB', 'Panel 1', ' Cooperativism and Green Finance ', '2024-10-19 17:56:58', 'd97b741edc4ae87d8048c0c40d30cb0b', 1, 1, 1, 'en-GB', '2024-10-15 16:56:55', NULL, '2024-10-15 16:56:55', NULL, 0, 0, 3, ),
(123, 'index.php?option=com_content&view=article&id=119', 'index.php?option=com_content&view=article&id=119:panel-2&catid=9&lang=en-GB', 'Panel 2', ' The role of cooperativism in mitigating and adapting to climate change ', '2024-10-19 17:57:18', '96097145ee764ebba3fa5d513c2559d4', 1, 1, 1, 'en-GB', '2024-10-15 17:01:07', NULL, '2024-10-15 17:01:07', NULL, 0, 0, 3, ),
